def longestDistinctLetterPath(board):
    m, n = len(board), len(board[0])
    distinct = len({x for row in board for x in row})
    nbrs = [[[(r + dr, c + dc) for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
              if 0 <= r + dr < m and 0 <= c + dc < n] for c in range(n)] for r in range(m)]
    best = 0
    seen = set()

    def go(r, c, mask, length):
        nonlocal best
        if length > best:
            best = length
        if best == distinct:
            return
        for nr, nc in nbrs[r][c]:
            bit = 1 << board[nr][nc]
            if not mask & bit:
                key = (nr, nc, mask | bit)
                if key not in seen:
                    seen.add(key)
                    go(nr, nc, mask | bit, length + 1)
                    if best == distinct:
                        return

    for r in range(m):
        for c in range(n):
            go(r, c, 1 << board[r][c], 1)
            if best == distinct:
                return best
    return best
